<script setup>import { computed, onMounted, ref } from 'vue'; import { ArrowLeft, Check, Package, Truck } from 'lucide-vue-next'; import { RouterLink, useRoute } from 'vue-router'; import { orderService } from '../../services/orderService'; const route = useRoute(); const order = ref(null); const loading = ref(true); const error = ref(''); const statuses = ['pending', 'processing', 'shipped', 'delivered']; const currentIndex = computed(() => Math.max(0, statuses.indexOf(order.value?.status))); const date = (value) => value ? new Date(value).toLocaleDateString(undefined, { month: 'long', day: 'numeric', year: 'numeric' }) : ''; onMounted(async () => { try { order.value = (await orderService.get(route.params.id)).data; } catch { error.value = 'Unable to load this order.'; } finally { loading.value = false; } });</script>
<template><section class="container page-section"><RouterLink class="back-link" to="/orders"><ArrowLeft :size="16" /> Back to orders</RouterLink><div v-if="loading" class="state">Loading order...</div><p v-else-if="error" class="state error-state">{{ error }}</p><div v-else><div class="order-title"><div><p class="kicker">ORDER #{{ order.id }}</p><h1>Order details</h1><p>Placed {{ date(order.created_at) }}</p></div><span class="status-badge large" :class="`status-${order.status}`">{{ order.status }}</span></div><div class="tracking"><div v-for="(status, index) in statuses" :key="status" class="track-step" :class="{ complete: index <= currentIndex, current: index === currentIndex }"><span class="track-dot"><Check v-if="index < currentIndex" :size="14" /><Package v-else-if="index === currentIndex" :size="14" /></span><b>{{ status }}</b></div></div><div class="order-detail-layout"><div class="checkout-section"><h3>Products</h3><div v-for="item in order.items" :key="item.id" class="checkout-item"><img v-if="item.product?.image" :src="`/storage/${item.product.image}`" alt=""><div v-else class="cart-thumb">N</div><span>{{ item.product?.name || `Product #${item.product_id}` }} <small>Qty {{ item.quantity }}</small></span><strong>${{ Number(item.price * item.quantity).toLocaleString(undefined, { minimumFractionDigits: 2 }) }}</strong></div></div><aside class="summary"><h3>Order total</h3><div><span>Subtotal</span><strong>${{ Number(order.total_price).toLocaleString(undefined, { minimumFractionDigits: 2 }) }}</strong></div><div><span>Shipping</span><strong>Included</strong></div><hr><div class="summary-total"><span>Total</span><strong>${{ Number(order.total_price).toLocaleString(undefined, { minimumFractionDigits: 2 }) }}</strong></div><p class="muted"><Truck :size="16" /> Status updates are reflected from Laravel.</p></aside></div></div></section></template>
